use std::{vec, vec::Vec};

// Fixed observed wire vector, not generated by this implementation:
// https://github.com/iTzFrancesco/dji-rcn1c-flight-deck/blob/main/docs/protocollo-rcn1c.md
// The RC-N1C simulator request is test input only; no hardware transmission occurs.
pub(crate) const RC_N1C: [u8; 13] = [
    0x55, 0x0d, 0x04, 0x33, 0x0a, 0x06, 0xeb, 0x34, 0x40, 0x06, 0x01, 0x74, 0x24,
];

pub(crate) fn synthetic_frame(payload: &[u8]) -> Vec<u8> {
    assert!(payload.len() <= 1010);
    let length = (payload.len() + 13) as u16 | 0x0400;
    let mut bytes = vec![0x55];
    bytes.extend(length.to_le_bytes());
    bytes.push(crate::checksum::header(&bytes));
    bytes.extend([0xe2, 0x63, 0xff, 0xff, 0xff, 0xfe, 0xfd]);
    bytes.extend(payload);
    bytes.extend(crate::checksum::frame(&bytes).to_le_bytes());
    bytes
}
